prints["McCoyLoggingCorp"]={id="McCoyLoggingCorp",title="McCoy Logging Co.",text="LUMBERJACKS NEEDED\n\nReliable men needed for heavy work at our mill.\n\nWork includes usage of industrial equipment, as well as axes and saws for smaller scale splitting and custom woodworking. Ability to drive a truck considered a bonus.\n\nMcCoy Logging Co. Making trees useful since 1914.\n\nOld Mill Road, Muldraugh, KY",locations={{x=10339,y=9349}}}
printList[#printList+1]="McCoyLoggingCorp"
prints["NolansUsedCars"]={id="NolansUsedCars",title="Nolan's Used Cars",text="There's no lemons at Nolan's - only pre-loved cars at unbeatable prices.\n\nLooking for last year's models without this year's prices?\n\nCome on down to Nolan's!\n\nWant no-pressure advice on the car that's best for you?\n\nCome on down to Nolan's!\n\nNeed easy, low cost finance?\n\nCome on down to Nolan's!\n\nHere are just a couple of the recent models we sold...\n\n1987 Dash Elite - $2495  1990 Chevalier Dart - $1695\n\nNo matter your need, you'll leave my lot satisfied! \n\nCome on down to Nolan's!\n\nFind us! 23101 Dixie Highway, West Point, Kentucky",locations={{x=11679,y=8359}}}
printList[#printList+1]="NolansUsedCars"
prints["WestMapleCountryClub"]={id="WestMapleCountryClub",title="West Maple Country Club",text="West Maple Country Club: a slice of sporting heaven!\n\nOur world-class 18-hole golf course attracts professionals from all across the globe...\n\n... but golf is just ONE of our attractions!\n\nSwim in our pool.\nPlay tennis, squash or pool\nRelax and refuel in our cozy lounge, bar and restaurant.\n\nWith a 5%% discount on memberships for new members, and a 20%% discount for their wives, there's NEVER been a better time to join!\n\nCall (555)-WESTMCC or visit us on Lakeshore Parkway, Riverside.",locations={{x=5674,y=6489},{x=6074,y=6349}}}
printList[#printList+1]="WestMapleCountryClub"
prints["FashionaBelle"]={id="FashionaBelle",title="FashionaBelle",text="\"Je m'appelle Belle St. Clair.\"\n\n\"J'aime la mode!\"\n\n\"From my youth as a model in Paris, to my successful career as a designer... I have always been at the cutting edge...\"\n\n\"My first FashionaBelle store opened on the Champs-Élysées in 1959, and now my designs are worn all over the world!\"\n\nFashionaBelle.\n\nClothes of distinction, at fine prices.\n\n458 Main Street, Rosewood",locations={{x=8079,y=11529}}}
