prints["Delilah"]={id="Delilah",title="PS Delilah",text="Come onboard the Delilah!\n\nGrandpappy grew up on the riverboats of the Mississippi, and now you can live that life too...\nHe never forgot the smooth, easy sailing of those old boats. In 1932 he found the wreck of a paddle steamer stuck in the mud near St. Louis. With his two brothers, he bought the wreck and got to work.\nMy grandpappy's dream came true. His name was Adam Jones, and he named his ship the Delilah after his beloved wife.\nI am Captain Adam Jones III. I am proud to keep that dream alive.\nThe Delilah is now docked in your area. See the attached map for details.\n\nWe are now docked at River Front Park in Brandenburg!",locations={{x=2054,y=5699}}}
printList[#printList+1]="Delilah"
prints["BensCabin"]={id="BensCabin",title="Cabin for Rent (West Point)",text="Small remote lakeside cabin available for rent. West of West Point.\n\nGreat location for fishing and hunting. Heated by a wood stove.\n\nRunning water, indoor bathroom. One, single bed. Good time guaranteed.\n\n$40 per night. Call 555-3498 for info.",locations={{x=10194,y=6764}}}
