prints["DragRacingTrack"]={id="DragRacingTrack",title="Drag Racing Track",text="Racers! Join us at your local drag race strip!\n\nEntry fees from $15.\n\nTest your engine, get your best time on our oval circuit, or push to the limit offroad! \n\nEvery car is tested on its own merits, so come along to our circuit, just west of Crossroads Mall!\n\nSnack discount for racers!\n\nCaroline Staunton Road, Valley Station",locations={{x=12859,y=6159}}}
printList[#printList+1]="DragRacingTrack"
prints["ArtGalleryofLouisville"]={id="ArtGalleryofLouisville",title="Art Gallery of Louisville",text="Expand your mind, one painting at a time!\n\nExplore classical paintings like Night with Stars, Nomad Above the Gloom and Aaaaah!\n\nVenture upstairs for modern art including work by the award-winning Ashling Dwyer.\n\nFree entry for seniors. Half-price for under-12s.\n\nFind us in northern Louisville, two blocks south of the bridge, at 2023 North 1st Street.\n\n",locations={{x=12544,y=1394}}}
printList[#printList+1]="ArtGalleryofLouisville"
prints["FossoilField"]={id="FossoilField",title="Fossoil Field",text="GO BINKIES!\n\nCheer on the KENTUCKY BINKIES at the Fossoil Field stadium!\n\nRELAX in our renovated stands.\n\nGET delicious American food at our stands.\n\nENJOY bouncy organ music.\n\nWATCH the greatest baseball team ever to grace Kentucky!\n\nFun for all the family, AND corporate hospitality!\n\nWith thanks to our friends at Fossoil!\n\n3800 East Main Street, Louisville.",locations={{x=13014,y=1579}}}
printList[#printList+1]="FossoilField"
prints["SunstarMotel"]={id="SunstarMotel",title="Sunstar Motel",text="Stay with us at the Sunstar Motel!\n\n10%% discount for veterans and seniors.\n\nLocated in central Muldraugh, with full air conditioning and color TV\n\nFood available separately in our diner!\n\nRates:\nStandard Double/Twin singles: $25\nDouble and single twin: $30\nBedroom w/double bed and living room: $40\n\nSpecial rates for daytime 'meetings'!\n\n118 Dixie Highway, Muldraugh, KY",locations={{x=10629,y=9819}}}
printList[#printList+1]="SunstarMotel"
prints["HavishamSuites"]={id="HavishamSuites",title="Havisham Suites",text="The gateway to your dreams.\n\nLUXURY and RELAXATION.\n\nAn experience that will last a lifetime.\n\nAt Havisham Suites, we know experiences are more important than things. Our stunning Louisville location, two blocks south of the Ohio bridge, features two conference rooms, an auditorium, and over two hundred hotel rooms. Whether business or pleasure, a prime location, friendly staff, and professional cocktail artistes in our bar mean Havisham Suites has just what you need.\n\n130 Jackson Street, Louisville, Kentucky.",locations={{x=12654,y=1319}}}
printList[#printList+1]="HavishamSuites"
prints["LouisvilleBruiser"]={id="LouisvilleBruiser",title="Louisville Bruiser Factory",text="LOUISVILLE BRUISER\n\nThe Home of the Baseball Bat\n\nCome meet the makers of the official Baseball World Championship bats!\n\nThen take one home!\n\nHear the true origins of the most iconic bat in American history.\n\nCall 555-3009 to book your Sunday tour\n\n130 Bruiser Avenue, Louisville, KY",locations={{x=13259,y=1234}}}
printList[#printList+1]="LouisvilleBruiser"
prints["TheSeaShanty"]={id="TheSeaShanty",title="The Sea Shanty",text="Seafood Platter $9.99\nBattered Fish $5.99\nShrimp in Garlic Butter $6.99\n\nWhat do you do with a seafood platter?\nWhat do you do with fish so battered...\n\nSail along to the Sea Shanty, me hearties!\n\nTry our shrimp platter for $9.99!\nCrab and lobster specials every Saturday!\nDon't forget Tuesday's surf-and-turf special for $6.99!\n\n48 Waterfront Park, Louisville\n\nShow this flier to a server for a 10%% discount on lobster",locations={{x=12854,y=1209}}}
printList[#printList+1]="TheSeaShanty"
prints["ScarletOakDistillery"]={id="ScarletOakDistillery",title="Scarlet Oak Distillery",text="SCARLET OAK\nTHE WORLD'S FINEST BOURBON\n\nAged to perfection. We've been brewing since 1910.\nThe favorite of workmen and presidents alike.\nTake a sip and see what makes Scarlet Oak's bourbon the very best of the best.\n\nProud winner of the 1992 North American Brewer's Prize, The Finest of Imports Award, and the Elijah Craig Memorial Prize.\n\nVisit our factory for the full tour, and some samples along the way!\n455 Bourbon Way, Louisville, Kentucky",locations={{x=12024,y=1974}}}
printList[#printList+1]="ScarletOakDistillery"
prints["ReadyPrep"]={id="ReadyPrep",title="Ready Prep",text="Rising crime! Riots! Dangerous cults!\n\nYour FREEDOM is in danger!\n\nWe say: don't get scared - get prepared! \n\nSturdy Survival Knives\nThe Finest in Military Surplus Clothing\nTents That Can Withstand Hurricanes\nGuns For Hunting - And Self Defense\n\nCome down to Ready Prep in northwest Louisville just south of the Ohio.\n\nPrepare for the worst - with the very best!\n\n1104 4th Street, Louisville",locations={{x=12224,y=1319}}}
printList[#printList+1]="ReadyPrep"
prints["WellingtonHeightsGolfClub"]={id="WellingtonHeightsGolfClub",title="Wellington Heights Golf Club",text="See the sights at WELLINGTON HEIGHTS\n\nOur tough but fair nine-hole course at the northern side of Iroquois Park offers something for players of all skill levels.\n\nCome to our weekly lessons with Logan Barton, winner of the 1992 Riverside Classic. Club rental and group discounts available.\n\nEven if you're not a golfer, find top quality food and drink at our comfortable, large, and private clubhouse. Why not visit today?\n\nWELLINGTON HEIGHTS\nWe're well above par\n\nJoin us for a round today!",locations={{x=12984,y=2319},{x=13144,y=2354}}}
printList[#printList+1]="WellingtonHeightsGolfClub"
prints["LSU"]={id="LSU",title="Louisville State University",text="Let's go, LSU!\n\nKentucky's most prestigious educational institute - founded in 1798!\n\nStudy with us, whatever your future! Humanities, Computing, Communicable Viral Biology, Sports Psychology and so much more...\n\nHundreds of highly trained lecturers ensure a WORLD-CLASS education!\n\nAnd Louisville State isn't just about study...\nSports teams that regularly top state and national leagues\nClubs to join, and healthy local nightlife\nKeg parties\nFriendships that will last a lifetime.\n\nOpening the door to the rest of your life...\n\nOld Seminary Road, Louisville, Kentucky",locations={{x=12399,y=2299}}}
printList[#printList+1]="LSU"
prints["LectromaxManufacturingJobAd"]={id="LectromaxManufacturingJobAd",title="Lectromax Manufacturing Job Ad",text="JOB AVAILABLE\n\nLectromax Manufacturing is hiring an experienced operator to work in our factory southwest of Riverside.\n\nWork consists of cutting and shaping saw blades. Lathe and hydraulic press experience required.\n\nPlease send resumé and references to the address listed below. Salary negotiable.\n\n740 Olin Road, Riverside, Kentucky",locations={{x=5579,y=5929}}}
