prints["PileoCrepeJobAdCrossRoadsMall"]={id="PileoCrepeJobAdCrossRoadsMall",title="Pile o' Crepe Job Ad (Crossroads Mall)",text="Manager wanted at our outlet beside Crossroads Mall. Five years experience in busy environment required. Very competitive salary, company car.\n\nApply with resumé at address below, or call us on 555-3492.\n\n1125 Bearcamp Road, Valley Station, Kentucky",locations={{x=13609,y=5757}}}
