prints["WPTownHall"]={id="WPTownHall",title="West Point Town Hall",text="\"Hello there! I'm Richard Rosenwald, Mayor of West Point, the small town with the big heart!\"\n\nYou may not realize it, but our town hall is ALWAYS available to help, no matter the issue.\n\nDemocracy works best when it's open, and we're always open for you!\n\nNeed help with LOCAL LAWS?\nWant advice on PERMITS?\nNeed to know YOUR RIGHTS as an American citizen?\"\n\nCall my office on 555-2100, or visit me at the Town Hall on Main Street",locations={{x=11939,y=6875}}}
