prints["FiveAlarmChili"]={id="FiveAlarmChili",title="Five Alarm Firehouse Chili",text="You won't find hotter than Five Alarm Firehouse Chili!\n\nFor years, Fire Chief John Schwartz kept Brandenburg's brave firefighters well fed with the best chili in Kentucky. When the Chief retired, he purchased his old fire hall and turned it into a restaurant!\n\nCome taste the Chief's chili and see what all the fuss is about.\n\nIt's hotter than hell!\n\n1276 Boyd Road, Brandenburg, Kentucky.",locations={{x=2079,y=6319}}}
printList[#printList+1]="FiveAlarmChili"
prints["GoldenSunset"]={id="GoldenSunset",title="Golden Sunset Nursing Home",text="With 20 years experience, Golden Sunset is an elder care leader.\n\nSituated beside the Ohio, we provide nursing facilities, long term health assistance, and world class nutrition.\n\nEach resident has a private bedroom, a living area, and a color TV.\n\nWith a maximum of 15 residents, we can give each one special care, while ensuring they can make friends - and have fun!\n\nOur communal rooms include a gym, a pleasant garden, a cafeteria, and a reading room.\n\nCall us on 943-555-9433 to book a tour or receive a FREE brochure.\n\nThey looked after you. Now let us after them.\n\n422 Lawrence Street, Brandenburg, Kentucky",locations={{x=2203,y=5767}}}
