prints["GunsUnlimitedEchoCreek"]={id="GunsUnlimitedEchoCreek",title="Guns Unlimited (Echo Creek)",text="From Magnums to MSRs, from snake shot to buck shot and everything in between, visit...\n\nGuns Unlimited\nYour 2nd Amendment Playground\n\nWe stock...\n- firearms of all calibers\n- weapon accessories\n- ammunition\n- knives and survival gear\n... and more!\n\nTest your skills at our range. Get guidance from our elite instructors.\n\nBecause you never know what's going to happen next...\n\n901 Smith Road, Echo Creek, Kentucky",locations={{x=2571,y=10891}}}
