prints["OvoFarms"]={id="OvoFarms",title="Ovo Farms",text="Ovo Farms knows eggs. We're the favorite of housewives all over Kentucky.\n\nSince 1968, our chickens have produced over 750,000 eggs. That's a lot of omelettes!\n\nHow do we do it? By caring about our birds. They're not just chickens to us - they're family.\n\nFrom just a dollar a dozen, you can taste the love in our eggs!\n\n1245 Payne Road, Echo Creek, Kentucky.\n\n(Tours of Ovo Farms no longer available. Please do not enquire.)",locations={{x=4003,y=10795}}}
