prints["Sanatorium"]={id="Sanatorium",title="Sunderland Hills Sanatorium",text="Hunt ghosts in one of America's most HAUNTED locations every Sunday!\n\nSunderland Hills Sanatorium was opened in 1910 to deal with the \"white plague\" - tuberculosis.\n\nHUNDREDS of patients died here until it was closed down in 1961.\n\nThankfully the days of plague are now LONG behind us, but some say... on moonlit nights, you can still hear the cries and moans of patients...\n\nAre you BRAVE enough to join us?\n\nCall 943-555-SPOOK to book your tour!\n\nSunderland Hills Sanatorium, Brandenburg, Kentucky",locations={{x=4103,y=6451}}}
printList[#printList+1]="Sanatorium"
